  /* Snijdt de reeksen uit elkaar en voegt ze toe aan wat js/woorden.js al had.
     De gekozen speelwoorden blijven dus staan; hier komt alleen bij. */
  (function vulAan() {
    var set = DVL.WOORDENBOEKSET || (DVL.WOORDENBOEKSET = Object.create(null));
    var lijst = DVL.WOORDENBOEK || (DVL.WOORDENBOEK = []);
    var erbij = 0;
    var sleutel, reeks, lengte, i, woord;

    for (sleutel in BLOKKEN) {
      if (!Object.prototype.hasOwnProperty.call(BLOKKEN, sleutel)) continue;
      reeks = BLOKKEN[sleutel];
      lengte = +sleutel;
      for (i = 0; i < reeks.length; i += lengte) {
        woord = reeks.substr(i, lengte);
        if (set[woord] !== true) {
          set[woord] = true;
          lijst.push(woord);
          erbij++;
        }
      }
    }

    lijst.sort();
    DVL.WOORDENBOEK_BRON = "OpenTaal";
    DVL.WOORDENBOEK_ERBIJ = erbij;
  })();

